"""Alphatel Partner Support System (APSS) — main entry point."""
import streamlit as st
import streamlit.components.v1 as components
from sqlalchemy.exc import OperationalError

from core import auth
from core.db import engine

st.set_page_config(
    page_title="APSS — Alphatel Partner Support",
    page_icon="assets/favicon.png",
    layout="wide",
)

# Bootstrap DB / catch config errors early
try:
    engine()
except OperationalError as e:
    msg = "Password authentication failed" if "password authentication" in str(e) else str(e)
    st.error(f"Database connection failed: {msg}")
    st.stop()
except RuntimeError as e:
    st.error(str(e))
    st.stop()

# Inject logo at sidebar top via base64 background-image (bypasses Streamlit height cap)
_LOGO_B64 = ""
# Inject logo into sidebar via JS (CSS data: URLs are blocked on Streamlit Cloud)
components.html(f"""
<script>
(function() {{
    var B64 = "{_LOGO_B64}";
    function inject() {{
        try {{
            var doc = window.parent.document;
            if (doc.getElementById('apss-logo-custom')) return true;
            var sidebar = doc.querySelector('section[data-testid="stSidebar"]');
            if (!sidebar) return false;
            var inner = sidebar.querySelector('div');
            if (!inner) return false;
            var wrap = doc.createElement('div');
            wrap.id = 'apss-logo-custom';
            wrap.style.cssText = 'padding:10px 14px 6px;background:white;position:sticky;top:0;z-index:1000;border-bottom:1px solid #f0f0f0;';
            var img = doc.createElement('img');
            img.src = 'data:image/png;base64,' + B64;
            img.style.cssText = 'height:70px;width:auto;max-width:210px;display:block;';
            wrap.appendChild(img);
            inner.insertBefore(wrap, inner.firstChild);
            return true;
        }} catch(e) {{ return false; }}
    }}
    var t = 0;
    var iv = setInterval(function() {{
        if (inject() || t++ > 40) clearInterval(iv);
    }}, 150);
    new MutationObserver(inject).observe(
        window.parent.document.body, {{childList:true, subtree:true}}
    );
}})();
</script>
""", height=1, scrolling=False)

auth.gate()

MENU = {
    "Support": [
        ("views/dashboard.py",  "Dashboard",  "📊", "dashboard"),
        ("views/tickets.py",    "Tickets",    "🎫", "tickets"),
    ],
    "Management": [
        ("views/hotels.py",     "Hotels",     "🏨", "hotels"),
        ("views/agents.py",     "Agents",     "👥", "agents"),
        ("views/reports.py",    "Reports",    "📈", "reports"),
        ("views/settings.py",   "Settings",   "⚙️", "settings"),
    ],
}

home = list(MENU.values())[0][0]
st.navigation(
    {group: [st.Page(f, title=ti, icon=ic, url_path=u, default=(f, ti, ic, u) == home)
             for f, ti, ic, u in items]
     for group, items in MENU.items()}
).run()
